using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
public static partial class HospitalPatientTransfer {
 const string Folder="Assets/EmergencyDeconHospitalPatient";
 static Bounds VisibleBounds(Transform root){var rs=root.GetComponentsInChildren<Renderer>(true).Where(r=>r.enabled&&r.gameObject.activeInHierarchy).ToArray();if(rs.Length==0)throw new Exception("No visible geometry: "+root.name);var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);return b;}
 static GameObject MakePrefab(){Directory.CreateDirectory(Folder);var source=EditorSceneManager.OpenPreviewScene("Assets/Scenes/Hospital_Evaluation.unity");try{var patient=All<Transform>(source).Single(t=>t.name=="Patient_Supine");var wound=All<Transform>(source).Single(t=>t.name=="Simulated_Wound_Target").Find("Studio_Model");if(!wound)throw new Exception("Hospital wound visual missing");var copy=UnityEngine.Object.Instantiate(patient.gameObject);SceneManager.MoveGameObjectToScene(copy,source);copy.name="Hospital_Patient_Visual";copy.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var woundCopy=UnityEngine.Object.Instantiate(wound.gameObject,copy.transform,false);woundCopy.name="Hospital_Wound_Visual";woundCopy.transform.localPosition=patient.InverseTransformPoint(wound.position);woundCopy.transform.localRotation=Quaternion.Inverse(patient.rotation)*wound.rotation;woundCopy.transform.localScale=wound.lossyScale;foreach(var mb in copy.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(mb);foreach(var c in copy.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var r in copy.GetComponentsInChildren<Renderer>(true)){GameObjectUtility.SetStaticEditorFlags(r.gameObject,0);r.lightProbeUsage=LightProbeUsage.BlendProbes;r.reflectionProbeUsage=ReflectionProbeUsage.BlendProbes;r.lightmapIndex=-1;if(r is MeshRenderer mr)mr.receiveGI=ReceiveGI.LightProbes;}return PrefabUtility.SaveAsPrefabAsset(copy,Folder+"/Hospital_Patient_Visual.prefab");}finally{EditorSceneManager.ClosePreviewScene(source);}}
 static void Apply(){if(EditorApplication.isPlaying||UnityEditor.Lightmapping.isRunning)throw new Exception("Edit mode without baking required");var current=SceneManager.GetActiveScene();if(current.isDirty)EditorSceneManager.SaveScene(current);string returnPath=current.path;var prefab=MakePrefab();var summaries=new List<string>();foreach(var path in EmergencyLightingWorkbench.Scenes){var s=EditorSceneManager.OpenScene(path,OpenSceneMode.Single);var patient=All<Transform>(s).Single(t=>t.name=="Patient"&&t.parent==null);var original=patient.Find("Patient_Body");if(!original)throw new Exception("Original patient missing");var oldBounds=original.GetComponent<Renderer>().bounds;var blood=patient.Find("Blood");if(!blood)throw new Exception("Existing Blood target missing");var forceps=All<MonoBehaviour>(s).Where(c=>c&&(c is Forceps||c is EvaluationForceps)).ToArray();if(forceps.Length!=1)throw new Exception("Unexpected forceps count");var so=new SerializedObject(forceps[0]);var target=so.FindProperty("targetObject");if(target.objectReferenceValue!=blood.gameObject)throw new Exception("Forceps target is not the original Blood");var existing=patient.Find("Hospital_Patient_Visual");if(existing)UnityEngine.Object.DestroyImmediate(existing.gameObject);var visual=(GameObject)PrefabUtility.InstantiatePrefab(prefab,s);visual.transform.SetParent(patient,false);visual.transform.localPosition=Vector3.zero;visual.transform.localRotation=Quaternion.identity;visual.transform.localScale=Vector3.one;var b=VisibleBounds(visual.transform);float scale=oldBounds.size.z/b.size.z;visual.transform.localScale=Vector3.one*scale;b=VisibleBounds(visual.transform);visual.transform.position+=new Vector3(oldBounds.center.x-b.center.x,oldBounds.min.y-b.min.y,oldBounds.center.z-b.center.z);
 original.gameObject.SetActive(false);foreach(var t in patient.Cast<Transform>().Where(t=>t.name=="Studio_Patient_Gown"||t.name=="Patient_Gown"))t.gameObject.SetActive(false);
 foreach(var r in visual.GetComponentsInChildren<MeshRenderer>().Where(r=>!PathOf(r.transform).Contains("Hospital_Wound_Visual"))){var scan=new GameObject("Patient_ScanCollider_"+r.name);scan.transform.SetParent(r.transform,false);var mc=scan.AddComponent<MeshCollider>();mc.sharedMesh=r.GetComponent<MeshFilter>().sharedMesh;mc.convex=false;mc.isTrigger=false;}
 var woundVisual=visual.transform.Find("Hospital_Wound_Visual");var wb=VisibleBounds(woundVisual);blood.SetPositionAndRotation(wb.center,Quaternion.identity);blood.localScale=Vector3.one;foreach(var r in blood.GetComponentsInChildren<Renderer>(true))r.enabled=false;var box=blood.GetComponent<BoxCollider>();box.enabled=true;box.isTrigger=true;box.center=Vector3.zero;box.size=Vector3.Max(wb.size+new Vector3(.025f,.025f,.025f),new Vector3(.075f,.035f,.085f));blood.gameObject.SetActive(true);
 var scanTarget=patient.Find("Patient_WoundScanCollider");if(!scanTarget){scanTarget=new GameObject("Patient_WoundScanCollider").transform;scanTarget.SetParent(patient,false);}scanTarget.SetPositionAndRotation(blood.position,Quaternion.identity);scanTarget.localScale=Vector3.one;var sc=scanTarget.GetComponent<BoxCollider>();if(!sc)sc=scanTarget.gameObject.AddComponent<BoxCollider>();sc.isTrigger=true;sc.center=Vector3.zero;sc.size=box.size;
 Physics.SyncTransforms();ValidateScene(s);EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);summaries.Add(s.name+": hospital patient scale="+scale.ToString("F3")+", wound="+wb.center.ToString("F4")+", Blood size="+box.size.ToString("F4")+", existing forceps reference preserved.");}
 AssetDatabase.SaveAssets();EditorSceneManager.OpenScene(returnPath,OpenSceneMode.Single);File.WriteAllLines(Out+"/applied.txt",summaries);File.WriteAllText(Out+"/status.txt","APPLIED");}
 static void ValidateScene(Scene s){var patient=All<Transform>(s).Single(t=>t.name=="Patient"&&t.parent==null);var blood=patient.Find("Blood");var visual=patient.Find("Hospital_Patient_Visual");var wound=visual.Find("Hospital_Wound_Visual");var box=blood.GetComponent<BoxCollider>();var scan=patient.Find("Patient_WoundScanCollider").GetComponent<BoxCollider>();if(!visual.gameObject.activeInHierarchy||!wound.gameObject.activeInHierarchy||patient.Find("Patient_Body").gameObject.activeSelf)throw new Exception("Wrong patient visual active");if(blood.GetComponentsInChildren<Renderer>(true).Any(r=>r.enabled))throw new Exception("Duplicate Blood visuals remain");if(!box.enabled||!box.isTrigger||!scan.enabled||!scan.isTrigger||Vector3.Distance(box.bounds.center,VisibleBounds(wound).center)>.005f)throw new Exception("Wound collision alignment failed");foreach(var c in All<MonoBehaviour>(s).Where(c=>c&&(c is Forceps||c is EvaluationForceps))){var so=new SerializedObject(c);if(so.FindProperty("targetObject").objectReferenceValue!=blood.gameObject)throw new Exception("Forceps target lost");}Physics.SyncTransforms();var hits=Physics.OverlapSphere(box.bounds.center,.006f,~0,QueryTriggerInteraction.Collide);if(!hits.Contains(box)||!hits.Contains(scan))throw new Exception("Physics overlap misses wound targets");bool active=blood.gameObject.activeSelf;try{blood.gameObject.SetActive(false);Physics.SyncTransforms();var afterHits=Physics.OverlapSphere(scan.bounds.center,.006f,~0,QueryTriggerInteraction.Collide);if(afterHits.Contains(box)||!afterHits.Contains(scan))throw new Exception("Treatment-state physics failed");if(!wound.gameObject.activeInHierarchy||!scan.gameObject.activeInHierarchy)throw new Exception("Treatment completion hides wound/rescan target");}finally{blood.gameObject.SetActive(active);}if(visual.GetComponentsInChildren<MonoBehaviour>(true).Any())throw new Exception("Hospital gameplay scripts copied");if(visual.GetComponentsInChildren<Renderer>().Any(r=>r.sharedMaterials.Any(m=>!m)))throw new Exception("Missing material");}
 static void ValidateAll(){var original=SceneManager.GetActiveScene().path;var reports=new List<string>();foreach(var p in EmergencyLightingWorkbench.Scenes){var s=EditorSceneManager.OpenScene(p,OpenSceneMode.Single);Physics.SyncTransforms();ValidateScene(s);reports.Add(s.name+": PASS saved patient, Blood/forceps reference, wound alignment, cleanup-state rescan, materials.");}EditorSceneManager.OpenScene(original,OpenSceneMode.Single);File.WriteAllLines(Out+"/verified.txt",reports);File.WriteAllText(Out+"/status.txt","VERIFIED");}
 static void RenderPatient(){var s=SceneManager.GetActiveScene();var patient=All<Transform>(s).Single(t=>t.name=="Hospital_Patient_Visual");var rs=patient.GetComponentsInChildren<Renderer>();var b=VisibleBounds(patient);var layerStates=rs.Select(r=>(r.gameObject,r.gameObject.layer)).ToArray();var go=new GameObject("Patient verification camera");go.hideFlags=HideFlags.HideAndDontSave;var c=go.AddComponent<Camera>();SceneManager.MoveGameObjectToScene(go,s);c.enabled=false;c.scene=s;c.transform.position=b.center+new Vector3(1.2f,2f,.6f);c.transform.LookAt(b.center,Vector3.back);c.orthographic=true;c.orthographicSize=1.12f;c.nearClipPlane=.05f;c.farClipPlane=8;c.clearFlags=CameraClearFlags.SolidColor;c.backgroundColor=new Color(.15f,.17f,.19f);c.cullingMask=1<<30;c.GetUniversalAdditionalCameraData().allowXRRendering=false;var rt=new RenderTexture(1500,1200,24);rt.Create();var old=RenderTexture.active;var tex=new Texture2D(1500,1200,TextureFormat.RGB24,false);try{foreach(var x in layerStates)x.gameObject.layer=30;RenderPipeline.SubmitRenderRequest(c,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1500,1200),0,0);tex.Apply();File.WriteAllBytes("Documentation/HospitalPatientTransfer/Patient-after.png",tex.EncodeToPNG());}finally{foreach(var x in layerStates)x.gameObject.layer=x.layer;RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}File.WriteAllText(Out+"/status.txt","RENDERED");}
}


